package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BZip2CompressorInputStream_read_TriageGen1Test {

    /**
     * Helper to create a valid BZip2 stream for testing.
     * BZip2 format requires specific headers. Using a minimal valid compressed stream.
     */
    private InputStream createValidBZip2Stream(byte[] data) throws IOException {
        // For the purpose of unit testing the 'read' method logic, 
        // we mock the internal behavior by wrapping a custom stream 
        // or using a real one. However, since read0() is protected/internal,
        // we will use a spy-like approach or a real compressed byte array.
        // Here we use a real compressed byte array to ensure the stream is "open".
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream bzOut = 
            new org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream(baos);
        bzOut.write(data);
        bzOut.finish();
        bzOut.close();
        return new ByteArrayInputStream(baos.toByteArray());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_OffsNegative() throws IOException {
        InputStream is = createValidBZip2Stream(new byte[]{1, 2, 3});
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);
        bzIn.read(new byte[10], -1, 5);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_LenNegative() throws IOException {
        InputStream is = createValidBZip2Stream(new byte[]{1, 2, 3});
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);
        bzIn.read(new byte[10], 0, -1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRead_OutOfBounds() throws IOException {
        InputStream is = createValidBZip2Stream(new byte[]{1, 2, 3});
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);
        bzIn.read(new byte[5], 3, 3); // 3 + 3 > 5
    }

    @Test(expected = IOException.class)
    public void testRead_StreamClosed() throws IOException {
        InputStream is = createValidBZip2Stream(new byte[]{1, 2, 3});
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);
        bzIn.close();
        bzIn.read(new byte[5], 0, 2);
    }

    @Test
    public void testRead_SuccessFull() throws IOException {
        byte[] inputData = {10, 20, 30, 40, 50};
        InputStream is = createValidBZip2Stream(inputData);
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);

        byte[] dest = new byte[5];
        int bytesRead = bzIn.read(dest, 0, 5);

        assertEquals(5, bytesRead);
        assertArrayEquals(inputData, dest);
        bzIn.close();
    }

    @Test
    public void testRead_SuccessPartial() throws IOException {
        byte[] inputData = {10, 20, 30, 40, 50};
        InputStream is = createValidBZip2Stream(inputData);
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);

        byte[] dest = new byte[5];
        // Read only 3 bytes
        int bytesRead = bzIn.read(dest, 1, 3);

        assertEquals(3, bytesRead);
        assertEquals((byte) 20, dest[1]);
        assertEquals((byte) 30, dest[2]);
        assertEquals((byte) 40, dest[3]);
        bzIn.close();
    }

    @Test
    public void testRead_EndOfStream() throws IOException {
        byte[] inputData = {10, 20};
        InputStream is = createValidBZip2Stream(inputData);
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);

        byte[] dest = new byte[10];
        // First read
        int firstRead = bzIn.read(dest, 0, 10);
        // It might read less than 10 if data is small

        // Second read should return -1
        int secondRead = bzIn.read(dest, 0, 10);
        assertEquals(-1, secondRead);
        bzIn.close();
    }

    @Test
    public void testRead_ZeroLen() throws IOException {
        byte[] inputData = {10, 20};
        InputStream is = createValidBZip2Stream(inputData);
        BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(is);

        byte[] dest = new byte[5];
        int bytesRead = bzIn.read(dest, 0, 0);

        // According to implementation: (destOffs == offs) ? -1 : ...
        // If len is 0, destOffs stays equal to offs, so it returns -1
        assertEquals(-1, bytesRead);
        bzIn.close();
    }
}
